class Solution {
public:
    std::vector<std::vector<int>> findMaximalUncoveredRanges(int n, std::vector<std::vector<int>>& ranges) {
        std::sort(ranges.begin(), ranges.end());
        std::vector<std::vector<int>> ans;
        int start = 0;
        for (const auto& r : ranges) {
            int l = r[0], right = r[1];
            if (start < l) {
                ans.push_back({start, l - 1});
            }
            if (start <= right) {
                start = right + 1;
            }
        }
        if (start < n) {
            ans.push_back({start, n - 1});
        }
        return ans;
    }
};

class Solution {
    public int[][] findMaximalUncoveredRanges(int n, int[][] ranges) {
        Arrays.sort(ranges, Comparator.comparingInt(a -> a[0]));
        List<int[]> ans = new ArrayList<>();
        int start = 0;
        for (int[] r : ranges) {
            int l = r[0], right = r[1];
            if (start < l) {
                ans.add(new int[]{start, l - 1});
            }
            if (start <= right) {
                start = right + 1;
            }
        }
        if (start < n) {
            ans.add(new int[]{start, n - 1});
        }
        return ans.toArray(new int[ans.size()][]);
    }
}

var findMaximalUncoveredRanges = function(n, ranges) {
    ranges.sort((a, b) => a[0] - b[0]);
    const ans = [];
    let start = 0;
    for (const [l, r] of ranges) {
        if (start < l) {
            ans.push([start, l - 1]);
        }
        if (start <= r) {
            start = r + 1;
        }
    }
    if (start < n) {
        ans.push([start, n - 1]);
    }
    return ans;
};
